Item.method_code:
const qd = aras.getItemProperty(item, 'query_definition');
const paramQuery = aras.newIOMItem('qry_QueryParameter', 'get');

paramQuery.setProperty('source_id', qd);
paramQuery.setAttribute('select', 'name');
const paramQueryResult = paramQuery.apply();

const valueArray = [];
const itemCount = paramQueryResult.getItemCount();
for (let i = 0; i < itemCount; i++) {
	const paramItem = paramQueryResult.getItemByIndex(i);
	const paramName = paramItem.getProperty('name');

	valueArray.push(paramName);
}

grid.columns_Experimental.set(colNumber, 'editType', 'FilterComboBox');
grid.columns_Experimental.set(colNumber, 'comboList', valueArray);
